import sys

class NumberTheory:
    class Mod998:
        def __init__(self):
            self.modulus_value = 998244353

        def modulus(self):
            return self.modulus_value

        def fInv(self, n):
            # Placeholder for modular inverse precomputation if needed
            pass

        def mult(self, a, b, inv=None):
            if inv is not None:
                return (a * b) % self.modulus()
            return (a * b) % self.modulus()

        def add(self, a, b):
            return (a + b) % self.modulus()

        def subtract(self, a, b):
            return (a - b) % self.modulus()

        def ncr(self, n, r):
            # Placeholder for nCr calculation modulo modulus
            # For simplicity, using a direct calculation with factorials
            if r > n or r < 0:
                return 0
            numerator = 1
            denominator = 1
            for i in range(r):
                numerator = (numerator * (n - i)) % self.modulus()
                denominator = (denominator * (i + 1)) % self.modulus()
            return (numerator * pow(denominator, -1, self.modulus())) % self.modulus()

        def smallInv(self, n):
            # Modular inverse of n modulo modulus
            return pow(n, -1, self.modulus())

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])

    mod = NumberTheory.Mod998()
    mod.fInv(n + m)

    phaseSize = 1
    p = 1
    i = 0
    while p != 0:
        p = (p * (n - i)) % mod.modulus()
        p = (p * mod.smallInv(n + m - i)) % mod.modulus()
        phaseSize = (phaseSize + p) % mod.modulus()
        i += 1

    answer = 0
    for k in range(1, n + 1):
        numPhases = (m + k) * mod.smallInv(k) % mod.modulus()
        e = (numPhases * phaseSize) % mod.modulus()
        term = (mod.ncr(n, k) * e) % mod.modulus()
        if k % 2 == 1:
            answer = (answer + term) % mod.modulus()
        else:
            answer = (answer - term) % mod.modulus()

    print(answer)

